SELECT json_build_object('intent',o.id,'header',r.id,'actor',u.username,'sent',o."sentAt" IS NOT NULL,'completed',o."completedAt" IS NOT NULL,'attempts',o.attempts,'state',o.status) FROM notification_outbox_intents o JOIN "ActivityRegistration" r ON r.id=o."aggregateId" JOIN "User" u ON r."memberId"=u."memberId" WHERE r."activityId"=:'target' AND o."aggregateType"='activity_registration' ORDER BY o."createdAt",o.id;
